package com.miniforce.service;
import com.miniforce.dto.ContestDtos.*; import com.miniforce.exception.*; import com.miniforce.model.*; import com.miniforce.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ContestService {
 private final ContestRepository contests;private final ContestProblemRepository contestProblems;private final ContestParticipantRepository participants;private final ProblemService problems; public ContestService(ContestRepository c,ContestProblemRepository cp,ContestParticipantRepository pa,ProblemService p){contests=c;contestProblems=cp;participants=pa;problems=p;}
 public List<ContestResponse> all(){return contests.findAllByOrderByStartsAtAsc().stream().map(ContestResponse::from).toList();} public ContestResponse get(Long id){return ContestResponse.from(entity(id));} private Contest entity(Long id){return contests.findById(id).orElseThrow(()->new NotFoundException("Contest not found"));}
 public List<ContestProblemResponse> problems(Long id,User user){Contest c=entity(id);if(c.getStatus()==ContestStatus.UPCOMING&&(user==null||user.getRole()!=Role.ADMIN))throw new ConflictException("Contest problems are hidden until the contest starts");return contestProblems.findByContestId(id).stream().map(x->new ContestProblemResponse(x.getProblem().getId(),x.getProblem().getSlug(),x.getProblem().getTitle(),x.getProblem().getDifficulty(),x.getPoints())).toList();}
 @Transactional(readOnly=true) public List<ContestLeaderboardEntry> leaderboard(Long id){entity(id);List<ContestParticipant> list=participants.leaderboard(id);List<ContestLeaderboardEntry> result=new ArrayList<>();for(int i=0;i<list.size();i++){result.add(new ContestLeaderboardEntry(i+1,com.miniforce.dto.UserResponse.from(list.get(i).getUser()),list.get(i).getScore()));}return result;}
 @Transactional public ContestResponse join(Long id,User user){Contest c=entity(id);if(c.getStatus()==ContestStatus.ENDED)throw new ConflictException("This contest has ended");if(!participants.existsByContestIdAndUserId(id,user.getId())){ContestParticipant p=new ContestParticipant();p.setContest(c);p.setUser(user);participants.save(p);}return ContestResponse.from(c);}
 @Transactional public ContestResponse create(ContestRequest r){Contest c=new Contest();applyFields(c,r);contests.save(c);syncProblems(c,r.problemIds());return ContestResponse.from(c);} @Transactional public ContestResponse update(Long id,ContestRequest r){Contest c=entity(id);applyFields(c,r);contestProblems.deleteAll(contestProblems.findByContestId(c.getId()));syncProblems(c,r.problemIds());return ContestResponse.from(c);} @Transactional public void delete(Long id){contests.delete(entity(id));}
 private void applyFields(Contest c,ContestRequest r){if(!r.endsAt().isAfter(r.startsAt()))throw new IllegalArgumentException("Contest end time must be after start time");c.setTitle(r.title().trim());c.setDescription(r.description()==null?"":r.description().trim());c.setStatus(r.status());c.setStartsAt(r.startsAt());c.setEndsAt(r.endsAt());c.setRated(r.rated());}
 private void syncProblems(Contest c,Set<Long> ids){if(ids!=null){for(Long problemId:ids){ContestProblem cp=new ContestProblem();cp.setContest(c);cp.setProblem(problems.entity(problemId));cp.setPoints(100);contestProblems.save(cp);}}}
}
